//! Oracle fuzz tests for the original's random number helpers at 0x106308, 0x106380, 0x1063b8 and 0x106408 (generated by
//! `factory gen`; the spec is the static scan's inference plus the generator word). The ports are the methods of `kh2_game_core::rng::Lcg`.
//! The generator word is the 64-bit state at reent +0xa8 (`0x373aa8`, behind the pointer at `0x373cf0`), randomised before every case, so
//! the cases run over random generator states; the word is compared after the call too (each helper steps it once).
//! Skips without a disc (KH2_ISO or local/iso.txt); fails without one when KH2_REQUIRE_DISC=1.

use kh2_factory::fuzz::*;
use kh2_game_core::rng::Lcg;

/// The generator word: eight bytes at `*(0x373cf0) + 0xa8`.
const WORD: (u32, u32, bool) = (0x373aa8, 8, true);

fn lcg(c: &mut Case) -> Lcg {
    Lcg(u64::from_le_bytes(c.global(0)[..8].try_into().unwrap()))
}

fn store(c: &mut Case, g: Lcg) {
    c.global(0)[..8].copy_from_slice(&g.0.to_le_bytes());
}

const BELOW: Spec = Spec {
    addr: 0x106308,
    args: &[Arg::Int(&[0, 1, 2, 100, 20001, -1])],
    floats: 0,
    ret: Ret::Int,
    globals: &[WORD],
    stubs: &[],
    nulls: true,
};

#[test]
fn orig_106308_matches_the_game() {
    let Some(st) = fuzz(&BELOW, 4000, |c| {
        let mut g = lcg(c);
        let v = g.below(c.int(0) as u32);
        store(c, g);
        Out::int(v as i32 as i64)
    }) else { return };
    eprintln!("{} cases equal, {} interpreter steps in {:.3} s", st.cases, st.steps, st.secs);
}

const BETWEEN: Spec = Spec {
    addr: 0x106380,
    args: &[Arg::Int(&[0, 1]), Arg::Int(&[0, 1, 6, 100])],
    floats: 0,
    ret: Ret::Int,
    globals: &[WORD],
    stubs: &[],
    nulls: true,
};

#[test]
fn orig_106380_matches_the_game() {
    let Some(st) = fuzz(&BETWEEN, 4000, |c| {
        let mut g = lcg(c);
        let v = g.between_int(c.int(0), c.int(1));
        store(c, g);
        Out::int(v as i64)
    }) else { return };
    eprintln!("{} cases equal, {} interpreter steps in {:.3} s", st.cases, st.steps, st.secs);
}

const FRAC: Spec = Spec {
    addr: 0x1063b8,
    args: &[],
    floats: 1,
    ret: Ret::Float,
    globals: &[WORD],
    stubs: &[],
    nulls: true,
};

#[test]
fn orig_1063b8_matches_the_game() {
    let Some(st) = fuzz(&FRAC, 4000, |c| {
        let mut g = lcg(c);
        let v = g.frac(c.float(0));
        store(c, g);
        Out::float(v)
    }) else { return };
    eprintln!("{} cases equal, {} interpreter steps in {:.3} s", st.cases, st.steps, st.secs);
}

const RANGE: Spec = Spec {
    addr: 0x106408,
    args: &[],
    floats: 2,
    ret: Ret::Float,
    globals: &[WORD],
    stubs: &[],
    nulls: true,
};

#[test]
fn orig_106408_matches_the_game() {
    let Some(st) = fuzz(&RANGE, 4000, |c| {
        let mut g = lcg(c);
        let v = g.range(c.float(0), c.float(1));
        store(c, g);
        Out::float(v)
    }) else { return };
    eprintln!("{} cases equal, {} interpreter steps in {:.3} s", st.cases, st.steps, st.secs);
}
